void fclose_wrapper(FILE **fp) {
    if (*fp) {
        fclose(*fp);
    }
    *fp = NULL;
}

// Resource allocated on the stack (local scope)
__attribute__((cleanup(fclose_wrapper)))
FILE *cfg_handle = NULL;

cfg_handle = fopen("config.ini", "r");

if (cfg_handle == NULL) {
    // Handle error (cleanup routine is skipped if stack unwinds)
    return;
}

// Resource (cfg_handle) is automatically closed
// when the current function scope exits.
// Exception-safe cleanup mechanism.
